50:     /**
51:      * @dev Returns the price of a given `priceAggregator`
52:      * Return value has 6 decimal precision.
53:      * Returns 0 if Chainlink's price feed is broken or frozen.
54:      **/
55:     function getPrice(
56:         address priceAggregatorAddress,
57:         uint256 maxTimeout
58:     ) internal view returns (uint256 price) {
59:         IChainlinkAggregator priceAggregator = IChainlinkAggregator(priceAggregatorAddress);
60:         // First, try to get current decimal precision:
61:         uint8 decimals;
62:         try priceAggregator.decimals() returns (uint8 _decimals) {
63:             // If call to Chainlink succeeds, record the current decimal precision
64:             decimals = _decimals;
65:         } catch {
66:             // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
67:             return 0;
68:         }
69: 
70:         // Secondly, try to get latest price data:
71:         try priceAggregator.latestRoundData() returns (
72:             uint80 roundId,
73:             int256 answer,
74:             uint256 /* startedAt */,
75:             uint256 timestamp,
76:             uint80 /* answeredInRound */
77:         ) {
78:             // Check for an invalid roundId that is 0
79:             if (roundId == 0) return 0;
80:             if (checkForInvalidTimestampOrAnswer(timestamp, answer, block.timestamp, maxTimeout)) {
81:                 return 0;
82:             }
83:             // Adjust to 6 decimal precision.
84:             return uint256(answer).mul(PRECISION).div(10 ** decimals);
85:         } catch {
86:             // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
87:             return 0;
88:         }
89:     }
